T["clinicalManagement"].insert(4, step("preg", "Pregnancy and recurrence", "Same visit", ["Pregnant with symptomatic BV or Trichomonas: metronidazole 500 mg twice daily for 7 days; avoid secnidazole and tinidazole (CDC).", "Pregnant with candidiasis: topical azole for 7 days only, no fluconazole (CDC).", "Recurrent candidiasis (3 or more a year): induction then weekly fluconazole for 6 months; check glucose (CDC)."]))
